type Model = { count: Int where it >= 0 && it <= 55 }

type Msg = Up | Down | Reset

fn init() -> Model = Model { count: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  Up => if m.count + 5 <= 55 { m with { count: m.count + 5 } } else { m with { count: 55 } }
  Down => if m.count >= 5 { m with { count: m.count - 5 } } else { m with { count: 0 } }
  Reset => init()
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Seats"),
      Html.paragraph("Seats: " ++ m.count.toStr() ++ " of 55"),
      Html.row([Html.button("-", Down), Html.button("+", Up), Html.button("Reset", Reset)])
    ]
  )

test startsAtZero = init().count == 0

test upAddsOneStep = update(init(), Up).count == 5

test downStopsAtZero = update(init(), Down).count == 0

test upStopsAtTheLimit =
  update(
    update(
      update(
        update(
          update(
            update(
              update(
                update(update(update(update(update(update(init(), Up), Up), Up), Up), Up), Up),
                Up
              ),
              Up
            ),
            Up
          ),
          Up
        ),
        Up
      ),
      Up
    ),
    Up
  ).count <=
    55

test resetGoesBack = update(update(init(), Up), Reset).count == 0
```

