Task: A sign-in form with a username box and a password box and a Sign in button. The username needs at least 4 characters and the password at least 6. Below the form show the first problem ("Username too short", "Password too short") or, if both are fine, "Ready to sign in". Pressing Sign in with a valid form shows "Welcome, <username>!"; otherwise nothing happens.

Your program:
```
type Model = { user: Str, pass: Str, welcome: Str }

type Msg = User(Str) | Pass(Str) | SignIn

fn init() -> Model = Model { user: "", pass: "", welcome: "" }

fn problem(user: Str, pass: Str) -> Str = if user.trim().len() < 4 {
  "Username too short"
} else if pass.len() < 6 { "Password too short" } else { "" }

fn update(m: Model, msg: Msg) -> Model = match msg {
  User(s) => m with { user: s, welcome: "" }
  Pass(s) => m with { pass: s, welcome: "" }
  SignIn => if problem(m.user, m.pass).isEmpty() {
    m with { welcome: "Welcome, " ++ m.user.trim() ++ "!" }
  } else { m }
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Sign in"),
      Html.input(m.user, s => User(s)),
      Html.input(m.pass, s => Pass(s)),
      Html.button(SignIn),
      Html.paragraph(
        if !m.welcome.isEmpty() { m.welcome } else if problem(m.user, m.pass).isEmpty() {
          "Ready to sign in"
        } else { problem(m.user, m.pass) }
      )
    ]
  )

test shortUsername = problem("aaa", "pppppp") == "Username too short"

test shortPassword = problem("aaaa", "ppppp") == "Password too short"

test validForm = problem("aaaa", "pppppp").isEmpty()

test welcomesValidUsers =
  update(update(update(init(), User("aaaa")), Pass("pppppp")), SignIn).welcome == "Welcome, aaaa!"

test refusesInvalidUsers = update(init(), SignIn).welcome.isEmpty()
```

