// day 0 of the clock (1 January 1970) was a Thursday; 0 = Monday ... 6 = Sunday
fn weekday(t: Int) -> Int = if t < 0 { 0 } else { (t / 86400 + 3) % 7 }

fn dayName(d: Int) -> Str = match d {
  0 => "Monday"
  1 => "Tuesday"
  2 => "Wednesday"
  3 => "Thursday"
  4 => "Friday"
  5 => "Saturday"
  _ => "Sunday"
}

