type Model = { a: Int where it >= 0, b: Int where it >= 0 }

type Msg = ScoreA(Int) | ScoreB(Int) | NewGame

fn init() -> Model = Model { a: 0, b: 0 }

fn update(m: Model, msg: Msg) -> Model = match msg {
  ScoreA(n) => if n > 0 { m with { a: m.a + n } } else { m }
  ScoreB(n) => if n > 0 { m with { b: m.b + n } } else { m }
  NewGame => init()
}

fn leader(m: Model) -> Str = if m.a > m.b { "Home leads" } else if m.b > m.a { "Away leads" } else {
  "Tied"
}

fn save(m: Model) -> Str = m.a.toStr() ++ "," ++ m.b.toStr()

fn restore(s: Str) -> Option[Model] = {
  let parts = s.split(",")
  match parts.first() {
    Some(x) => match x.toInt() {
      Some(a) => match parts.drop(1).first() {
        Some(y) => match y.toInt() {
          Some(b) => if a >= 0 && b >= 0 { Some(Model { a: a, b: b }) } else { None }
          None => None
        }
        None => None
      }
      None => None
    }
    None => None
  }
}

fn view(m: Model) -> Html[Msg] =
  Html.col(
    [
      Html.heading("Home " ++ m.a.toStr() ++ " : " ++ m.b.toStr() ++ " Away"),
      Html.paragraph(leader(m)),
      Html.row(
        [
          Html.button("Home +1", ScoreA(1)),
          Html.button("Home +2", ScoreA(2)),
          Html.button("Home +3", ScoreA(3))
        ]
      ),
      Html.row(
        [
          Html.button("Away +1", ScoreB(1)),
          Html.button("Away +2", ScoreB(2)),
          Html.button("Away +3", ScoreB(3))
        ]
      ),
      Html.button("New game", NewGame)
    ]
  )

