  Add => (x + y).toStr()
  Multiply => (x * y).toStr()
  Divide => if y == 0 { "Cannot divide by zero." } else { (x / y).toStr() }
}

fn answer(op: Op, a: Str, b: Str) -> Str = match a.trim().toInt() {
