  Html.col(
    [
      Html.heading("Calculator"),
      Html.row([Html.input(m.a, s => SetA(s)), Html.input(m.b, s => SetB(s))]),
      Html.row(
        [
          Html.button("+", Apply(Add)),
          Html.button("*", Apply(Multiply)),
          Html.button("/", Apply(Divide))
